F=np.load('feats.npz'); y=F['y']; folds=np.load('folds.npy')
def stdz(X,tr): mu=X[tr].mean(0); sd=X[tr].std(0)+1e-6; return (X-mu)/sd
def ridge(X,Y,lam): return np.linalg.solve(X.T@X+lam*np.eye(X.shape[1]),X.T@Y)
def evalfn(build, lam):
    accs=[]
    for f in range(5):
        tr=folds!=f; te=~tr
        Z=build(tr); mu=Z[tr].mean(0); Z=Z-mu
        Y=np.eye(8)[y[tr]]-1/8
        A=ridge(Z[tr],Y,lam); accs.append((np.argmax(Z[te]@A,1)==y[te]).mean())
    return round(np.mean(accs),4)
